message.content:
{
  "gate_token": "wU54oNBpxtxKKm2yuEv6KQ",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept hill at dawn overlooking shattered spires; a parchment map weighed down with stones; broken banners flutter in the distance.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps.",
      "visual_description": "A single-eyed oil lamp burning blue against twilight, its flame curled like a pointing finger toward the city gates.guidance smoke spelling 'BEWARE'.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin fox scouts the cracked castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes peering through the bars of a colossal iron gate; weeds curl through the hinges.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass diver emerges from a shattered window.",
      "visual_description": "A figure in a clear diving helmet rising headfirst out of a tall broken window as if surfacing from water; coat shimmering with reflected ruins.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team meets in the empty plaza.",
      "visual_description": "A cracked fountain plaza scattered with torn royal banners; the four converge while the lamp hovers on a broken pedestal.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened faces watch from shuttered windows.",
      "visual_description": "Narrow alley lined with boarded houses; pale eyes peek through cracks; Mara raises a hand in reassurance, lamp casting warm circles.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol clanks past in the fog.",
      "visual_description": "Silhouettes of empty suits of armor marching mechanically through green fog; tin fox crouches behind a barrel, gears silent.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "They find the sleeping tax collector slumped at his post.",
      "visual_description": "A round official snoring over a ledger pillow, stamped papers stuck to his sleeves; a 'TOLL' sign hangs crooked above him.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara pries a sealed permit from his hand.",
      "visual_description": "Mara gently tugging a wax-sealed scroll from the snoring official's grip; the lamp glows nervously overhead.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a great winged beast drift across the rooftops.",
      "visual_description": "Distant shadow with vast wings circling above a cursed tower; the team ducks beneath a collapsed arcade, lamp dimming its eye.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Tin fox finds a hidden cellar mirror.",
      "visual_description": "A dusty cellar with a tall silvered mirror leaning against rubble; the clockwork fox's tail key glints as it nudges the frame.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "Glass diver dives through the mirror into the cursed tower.",
      "visual_description": "Ripples spreading across the mirror's surface as the helmeted figure plunges in, coat trailing reflected starlight.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Inside the tower, a magic door bars the way.",
      "visual_description": "A circular door carved with shifting runes glowing amber; the diver presses a gloved palm to it; lamp's eye reflected in the brass.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The lamp whispers the door's true name.",
      "visual_description": "Close-up of the lamp flame stretching into a mouth shape; runes on the door rearranging into welcoming letters.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Mara maps an escape route through the wreckage.",
      "visual_description": "Mara crouched on a balcony, compass spinning, charcoal lines snaking across her parchment toward a distant stone bridge.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The rescued one is carried out through the mirror.",
      "visual_description": "Glass diver stepping back out of the silvered surface with a small bundled figure cradled in arms; mirror rippling like pond water.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols close in as alarms ring.",
      "visual_description": "Bells clanging atop ruined towers; metal silhouettes converging from three streets; tin fox sprints ahead, sparks at its heels.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the long bridge at sunrise.",
      "visual_description": "A crumbling stone bridge stretching over a misty chasm; the team silhouetted against pink dawn; behind them the city smolders, ahead open country.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

